INSERT INTO `product_detail` VALUES (1,'Việt Nam','Sữa bò tươi (96%), đường tinh luyện, chất ổn định (471, 460(i), 407, 466).','Ngon hơn khi uống lạnh. Lắc đều trước khi dùng.','Bảo quản nơi khô ráo, thoáng mát.',75.60,3.00,3.50,8.20,8.00,'{\"Vitamin A\": \"220 IU\", \"Vitamin D3\": \"120 IU\"}','{\"Canxi\": \"110 mg\", \"Photpho\": \"90 mg\"}',NULL),(2,'Việt Nam','Sữa bò tươi (100%).','Dùng trực tiếp. Thích hợp cho người kiêng đường.','Bảo quản nơi khô ráo, tránh ánh nắng.',60.00,3.10,3.30,4.60,4.60,'{\"Vitamin A\": \"180 IU\", \"Vitamin D3\": \"100 IU\"}','{\"Canxi\": \"120 mg\", \"Magie\": \"10 mg\"}',NULL),(3,'Việt Nam','Sữa bò tươi từ trang trại sinh thái Green Farm, đường, chất ổn định.','Dùng cho trẻ trên 1 tuổi.','Bảo quản nơi khô ráo.',70.20,2.90,3.40,7.50,7.00,'{\"Vitamin A\": \"200 IU\", \"Vitamin D3\": \"130 IU\"}','{\"Canxi\": \"115 mg\", \"Kẽm\": \"0.5 mg\"}',NULL),(4,'Việt Nam','Sữa, đường, dầu thực vật, vitamin A, D3, Canxi.','Mỗi ngày dùng 3 hộp để đủ vi chất.','Nơi thoáng mát.',72.00,3.00,3.20,8.00,8.00,'{\"Vitamin A\": \"500 IU\", \"Vitamin D3\": \"150 IU\", \"Vitamin B12\": \"0.5 µg\"}','{\"Canxi\": \"140 mg\", \"Magie\": \"15 mg\"}','Omega 3, DHA'),(5,'Việt Nam','Sữa, đường, nha đam (10%), men Streptococcus thermophilus.','Sử dụng ngay sau khi mở nắp.','Bảo quản lạnh 6-8 độ C.',105.00,3.20,2.80,16.50,16.00,'{\"Vitamin B1\": \"50 mcg\", \"Vitamin B2\": \"150 mcg\"}','{\"Canxi\": \"100 mg\"}','Collagen tự nhiên'),(6,'Việt Nam','Nước, đường, sữa bột, men Lactobacillus Casei 431.','Khuyên dùng 2 chai mỗi ngày.','Không cần bảo quản lạnh.',65.00,1.20,0.00,15.00,14.00,'{\"Vitamin D3\": \"50 IU\"}','{\"Canxi\": \"40 mg\"}','13 tỷ lợi khuẩn L.Casei 431'),(7,'Việt Nam','Sữa, mứt trái cây, vitamin nhóm B, chất xơ hòa tan.','Ăn trực tiếp.','Bảo quản lạnh 6-8 độ C.',90.00,2.80,2.50,14.00,13.00,'{\"Vitamin A\": \"250 IU\", \"Vitamin B6\": \"0.2 mg\"}','{\"Canxi\": \"90 mg\"}','Chất xơ hòa tan (Inulin)'),(8,'Việt Nam','Đường, sữa, dầu thực vật.','Dùng pha cà phê, làm bánh, ăn với bánh mì.','Đậy nắp kỹ sau khi dùng, bảo quản tủ lạnh.',338.00,4.60,10.80,56.00,56.00,'{\"Vitamin A\": \"200 IU\", \"Vitamin D\": \"40 IU\"}','{\"Canxi\": \"260 mg\", \"Photpho\": \"230 mg\"}',NULL),(9,'Việt Nam','Nước, đậu nành hạt (90%), đường, dầu đậu nành.','Uống liền. Ngon hơn khi uống lạnh.','Tránh ánh nắng mặt trời.',54.00,3.10,1.80,6.50,6.00,'{\"Vitamin A\": \"100 IU\", \"Vitamin E\": \"1.0 mg\"}','{\"Canxi\": \"20 mg\"}','Isoflavones (12mg)'),(10,'Việt Nam','Dịch hạt óc chó, sữa bò tươi, đường.','Lắc đều trước khi uống.','Bảo quản nơi khô ráo.',68.00,1.50,2.20,10.50,9.00,'{\"Vitamin A\": \"250 IU\", \"Vitamin E\": \"1.5 mg\", \"Vitamin PP\": \"2.0 mg\"}','{\"Canxi\": \"80 mg\", \"Phốt pho\": \"70 mg\"}','Omega-3 (80mg)');
